from pathlib import Path
import json,hashlib,shutil,html
from PIL import Image,ImageDraw,ImageFont
R=Path(__file__).resolve().parents[2];out=R/'assets/branding/products';out.mkdir(exist_ok=True);font=Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf');bold=font.with_name('DejaVuSans-Bold.ttf');atlas=Image.new('RGB',(1536,1536),'#e9e2cd');rows=[]
recipes=[('Hafer','HAFER','Vollkornflocken','500 g','2,49','3F6751','carton'),('Milch','MILCH','Frisch und mild','1 Liter','1,39','476C88','milk'),('Pasta','PASTA','Hartweizennudeln','500 g','1,89','A16443','carton'),('Tomaten','TOMATEN','Passierte Tomaten','400 g','1,59','985447','can'),('Bohnen','BOHNEN','Weisse Bohnen','400 g','1,49','9D8448','can'),('Apfel','APFELSAFT','Naturtrueber Saft','1 Liter','2,29','577052','bottle')]
for i,(sku,title,sub,amount,price,color,kind)in enumerate(recipes):
 im=Image.new('RGB',(512,768),'#eee8d5');d=ImageDraw.Draw(im);accent='#'+color;d.rectangle((20,20,492,748),outline=accent,width=7);d.rectangle((20,20,492,158),fill=accent);d.text((256,88),'MARKTGRUEN',font=ImageFont.truetype(str(bold),40),fill='#faf5e3',anchor='mm');d.text((256,248),title,font=ImageFont.truetype(str(bold),51 if len(title)<9 else 40),fill=accent,anchor='mm');d.text((256,312),sub,font=ImageFont.truetype(str(font),28),fill='#29352b',anchor='mm')
 # Original simple grain/leaf graphic, not a photographic product substitute.
 d.line((175,490,333,380),fill=accent,width=7)
 for j in range(6):
  x=190+j*23;y=480-j*16;d.ellipse((x-30,y-26,x+10,y-4),fill=accent);d.ellipse((x+5,y-1,x+43,y+23),fill=accent)
 d.text((256,575),amount,font=ImageFont.truetype(str(bold),36),fill=accent,anchor='mm');d.text((256,642),'Hausmarke / Winterlichtplatz',font=ImageFont.truetype(str(font),22),fill='#29352b',anchor='mm');d.rectangle((35,674,477,728),fill=accent);d.text((256,702),price+' EUR',font=ImageFont.truetype(str(bold),31),fill='#faf5e3',anchor='mm');x=(i%3)*512;y=(i//3)*768;atlas.paste(im,(x,y))
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="512" height="768" viewBox="0 0 512 768"><rect width="512" height="768" fill="#eee8d5"/><rect x="20" y="20" width="472" height="728" fill="none" stroke="{accent}" stroke-width="7"/><rect x="20" y="20" width="472" height="138" fill="{accent}"/><g font-family="DejaVu Sans,sans-serif" text-anchor="middle"><text x="256" y="101" font-size="40" font-weight="bold" fill="#faf5e3">MARKTGRUEN</text><text x="256" y="263" font-size="44" font-weight="bold" fill="{accent}">{title}</text><text x="256" y="322" font-size="28" fill="#29352b">{html.escape(sub)}</text><text x="256" y="587" font-size="36" fill="{accent}">{amount}</text><text x="256" y="649" font-size="22" fill="#29352b">Hausmarke / Winterlichtplatz</text></g><path d="M175 490 L333 380" fill="none" stroke="{accent}" stroke-width="7"/><g fill="{accent}"><ellipse cx="205" cy="456" rx="25" ry="11"/><ellipse cx="246" cy="454" rx="25" ry="11"/><ellipse cx="254" cy="422" rx="25" ry="11"/><ellipse cx="292" cy="419" rx="25" ry="11"/></g><rect x="35" y="674" width="442" height="54" fill="{accent}"/><text x="256" y="713" text-anchor="middle" font-family="DejaVu Sans,sans-serif" font-size="31" font-weight="bold" fill="#faf5e3">{price} EUR</text></svg>''';(out/(sku+'.svg')).write_text(svg);rows.append({'id':i,'sku':sku,'title':title,'category':kind,'label_cell_px':[x,y,x+512,y+768],'rgb_srgb':color,'concept_price_eur':price,'fictional_original_product':True})
p=out/'MARKTGRUEN-products-original-atlas.png';atlas.save(p);notice=Path('/usr/share/doc/fonts-dejavu-core/copyright');shutil.copyfile(notice,out/'DejaVu-font-rasterization-notice.txt');ledger={'stage':'Original fictional grocery graphic sources, not copied real brands; concept prices only','atlas':str(p.relative_to(R)),'atlas_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'atlas_dimensions':[1536,1536],'labels':rows,'project_graphic_license':'CC0 under project original-work licence; third-party human scans remain separate CC BY4','font_rasterization_only':{'name':'DejaVu Sans and DejaVu Sans Bold','font_file_sha256':hashlib.sha256(font.read_bytes()).hexdigest(),'bold_file_sha256':hashlib.sha256(bold.read_bytes()).hexdigest(),'notice':'DejaVu-font-rasterization-notice.txt','native_export_dependency':'None: actual label pixel data packed. Editable SVG has standard sans-serif fallback; font software not bundled.'}};(out/'manifest.json').write_text(json.dumps(ledger,indent=2)+'\n');print('ORIGINAL_FICTIONAL_GROCERY_LABEL_SOURCES_CREATED',len(rows),ledger['atlas_sha256'])
